//   isar_generator: ^3.1.0
//   build_runner: ^2.4.8

import 'package:isar/isar.dart';
import 'package:path_provider/path_provider.dart';
part 'message.g.dart';

@collection
class Message {
  Id id = Isar.autoIncrement;
  @Index(composite: [CompositeIndex('tenantId')])
  String threadId;
  String tenantId;
  String body;
  @Index() DateTime createdAt;
  @Index() bool unread;
  Message({required this.threadId, required this.tenantId, required this.body,
           required this.createdAt, required this.unread});
}

late final Isar isar;
Future<void> initIsar() async {
  final dir = await getApplicationDocumentsDirectory();
  isar = await Isar.open([MessageSchema], directory: dir.path, name: 'app');
}

// ────── Writes must be inside writeTxn ──────
Future<void> saveMessage(Message m) async {
  await isar.writeTxn(() async {
    await isar.messages.put(m);
  });
}

// ────── Typed query (indexed) ──────
Future<List<Message>> unreadForThread(String threadId, String tenantId) {
  return isar.messages
    .filter()
    .threadIdEqualTo(threadId)
    .and().tenantIdEqualTo(tenantId)
    .and().unreadEqualTo(true)
    .sortByCreatedAtDesc()
    .limit(50)
    .findAll();
}

// ────── Reactive stream — auto-updates on any write ──────
Stream<List<Message>> watchUnread(String threadId, String tenantId) =>
  isar.messages
    .filter()
    .threadIdEqualTo(threadId)
    .and().tenantIdEqualTo(tenantId)
    .and().unreadEqualTo(true)
    .sortByCreatedAtDesc()
    .watch(fireImmediately: true);

// ────── Full-text search (Isar 3 ships lightweight FTS) ──────
